function updateNow(){const t=queue[current];el('now').textContent=t?.name??'Выберите композицию';el('format').textContent=t?t.format.toUpperCase()+' / '+(t.mode==='ay'?'AY-3-8910':t.mode==='module'?'TRACKER':t.mode==='gme'?'CHIP':'AUDIO'):'READY';el('queuecount').textContent=queue.length+' треков';btn('stop').disabled=!active;btn('play').disabled=!queue.length;btn('prev').disabled=!queue.length;btn('next').disabled=!queue.length;el('miniNow').textContent=t?.name??'Музыка не выбрана';updateLike();updateMini()}
async function playAt(i:number,remember=true){if(i<0||i>=queue.length)return;const old=current;stopPlayback();if(remember&&old>=0&&old!==i)history.push(old);current=i;selected=i;listeningStarted=true;bag=bag.filter(x=>x!==i);const g=generation,t=queue[i];active=true;noteRecent(t);status('Загрузка…');renderQueue();updateNow();try{
 if(t.mode==='ay'){ayContext??=new AudioContext();await ayContext.resume();if(g!==generation)return;const f=t.file??await fetch('/api/media/'+t.id).then(async r=>{if(!r.ok)throw Error('Файл недоступен');return new File([await r.blob()],t.name)});if(g!==generation)return;ay=new PT3Music(ayContext,s=>{if(g===generation&&!paused)status(s)},()=>{if(g===generation){recordListening(true);failed.clear();advance(true)}},()=>{if(g===generation)onFailure('Ошибка AY-декодера')});if(!f)throw Error("Файл недоступен");await ay.load(f);if(g===generation&&paused)ay.setPaused(true)}
 else{await activate();if(g!==generation)return;const url=t.file?(objectURL=URL.createObjectURL(t.file)):'/api/'+(t.mode==='native'?'media/':'stream/')+t.id;audio.src=url;if(!paused)await audio.play();if(g===generation)status(paused?'Пауза':'Воспроизведение')}
 }catch(e){if(g===generation&&!paused)onFailure(String(e instanceof Error?e.message:e))}}
function onFailure(s:string){if(!active)return;const t=queue[current];if(t&&!t.file&&t.mode==='native'&&!fallback&&!ay){fallback=true;audio.src='/api/stream/'+t.id;audio.play().catch(()=>{if(active&&queue[current]===t)skipBad(s)});status('Декодирование на сервере');return}skipBad(s)}
