function advance(auto=false,skip=false){if(!queue.length)return;if(auto&&!skip&&repeat==='one'){playAt(current,false);return}let i=current;
 for(let j=0;j<queue.length;j++){if(shuffle){bag=bag.filter(x=>x!==current&&x<queue.length);if(!bag.length){if(auto&&repeat==='off'&&history.length>=queue.length-1){stopPlayback();updateNow();return}bag=queue.map((_,k)=>k).filter(k=>k!==current)}if(!bag.length)i=0;else{i=bag.splice(Math.floor(Math.random()*bag.length),1)[0]}}else{i++;if(i>=queue.length){if(auto&&repeat==='off'&&!skip){stopPlayback();updateNow();return}i=0}}if(!failed.has(i)){void playAt(i);return}}stopPlayback();updateNow()}
function add(ts:Track[]){if(!ts.length)return;const known=new Set(queue.map(t=>t.id));for(const t of ts)if(!known.has(t.id)&&queue.length<10000){queue.push(t);known.add(t.id)}bag=[];history=[];failed.clear();if(selected<0)selected=0;renderQueue();updateNow()}
