function indexFolders(){folderIndex=new Map();for(const t of library){const parts=t.path.split('/');parts.pop();let parent='';for(const name of parts){const path=parent?parent+'/'+name:name;let n=folderIndex.get(path);if(!n){n={path,name,parent,counts:{all:0}};folderIndex.set(path,n)}n.counts.all++;n.counts[t.source]=(n.counts[t.source]??0)+1;parent=path}}}
function validFolder(){while(folderPath&&(!folderIndex.has(folderPath)||!sourceCount(folderIndex.get(folderPath)!)))folderPath=folderPath.includes('/')?folderPath.slice(0,folderPath.lastIndexOf('/')):''}
function browseLibraryFolder(path:string){folderPath=path;folderPage=0;input('folderSearch').value='';renderLibrary()}
function renderFolderNav(){validFolder();const crumbs=el('folderCrumbs'),root=action('Все каталоги',()=>browseLibraryFolder(''));crumbs.replaceChildren(root);if(!folderPath)root.setAttribute('aria-current','page');let prefix='';for(const part of folderPath.split('/').filter(Boolean)){prefix=prefix?prefix+'/'+part:part;const dest=prefix;const sep=document.createElement('span');sep.textContent=' / ';const b=action(part,()=>browseLibraryFolder(dest));b.title=dest;if(dest===folderPath)b.setAttribute('aria-current','page');crumbs.append(sep,b)}btn('folderUp').disabled=!folderPath;
 const q=input('folderSearch').value.trim().toLocaleLowerCase();const nodes=[...folderIndex.values()].filter(n=>sourceCount(n)>0&&(q?(!folderPath||n.path.startsWith(folderPath+'/'))&&n.path.toLocaleLowerCase().includes(q):n.parent===folderPath)).sort((a,b)=>a.path.localeCompare(b.path,undefined,{numeric:true,sensitivity:'base'}));
 const pageSize=24,pages=Math.max(1,Math.ceil(nodes.length/pageSize));folderPage=Math.max(0,Math.min(pages-1,folderPage));const grid=el('folderGrid');grid.replaceChildren();for(const n of nodes.slice(folderPage*pageSize,(folderPage+1)*pageSize)){const b=action('',()=>browseLibraryFolder(n.path));b.className='library-folder';b.title=n.path;const icon=document.createElement('span');icon.className='folder-glyph';icon.setAttribute('aria-hidden','true');const label=document.createElement('span');label.className='folder-label';label.textContent=q?(folderPath?n.path.slice(folderPath.length+1):n.path):n.name;const count=document.createElement('small');count.textContent=String(sourceCount(n));count.title='Треков в папке и подпапках';b.append(icon,label,count);grid.append(b)}
 if(!nodes.length){const empty=document.createElement('span');empty.className='folder-empty';empty.textContent=q?'Папки не найдены':'Нет вложенных папок';grid.append(empty)}
 el('folderPages').hidden=pages===1;el('folderPageInfo').textContent=(folderPage+1)+' / '+pages+' · '+nodes.length+' папок';btn('folderPrev').disabled=folderPage===0;btn('folderNext').disabled=folderPage>=pages-1
}
function filtered(){const q=input('search').value.toLowerCase().trim(),src=select('source').value,recursive=input('folderRecursive').checked;return library.filter(t=>{const parent=t.path.includes('/')?t.path.slice(0,t.path.lastIndexOf('/')):'';return (libraryView==='all'||(libraryView==='likes'?taste.likes:taste.recent).includes(t.id))&&(src==='all'||t.source===src)&&(recursive?(!folderPath||parent===folderPath||parent.startsWith(folderPath+'/')):parent===folderPath)&&(!q||(t.name+' '+t.path).toLowerCase().includes(q))})}
function row(t:Track,i:number,forQueue:boolean){const r=document.createElement('div');r.className='track'+(forQueue&&i===selected?' selected':'')+(forQueue&&i===current?' current':'');r.tabIndex=0;const info=document.createElement('div');info.className='info';const title=document.createElement('strong');title.textContent=(forQueue?String(i+1).padStart(2,'0')+'  ':'')+t.name;const sub=document.createElement('small');sub.textContent=t.source==='local'?'Локальный файл':identity.role==='admin'?(t.source==='uploads'?'Загрузки':'Сервер')+' / '+t.path:t.path;info.append(title);if(!forQueue)info.append(sub);else r.title=sub.textContent;const ext=document.createElement('span');ext.className='ext';ext.textContent=t.format.toUpperCase();const b=document.createElement('button');b.textContent='▶';b.title='Играть';b.onclick=e=>{e.stopPropagation();if(forQueue){failed.clear();void playAt(i)}else{add([t]);failed.clear();void playAt(queue.findIndex(x=>x.id===t.id))}};const open=()=>{if(!forQueue)add([t]);failed.clear();void playAt(forQueue?i:queue.findIndex(x=>x.id===t.id))};r.append(info,ext);if(!forQueue)r.append(b);if(!t.file){const rating=makeRating(t,true);const negative=makeRating(t,false);r.append(rating,negative)}if(!forQueue){const plus=document.createElement('button');plus.textContent='+';plus.title='В очередь';plus.onclick=e=>{e.stopPropagation();add([t])};r.append(plus)}r.onclick=()=>{if(forQueue){selected=i;for(const [j,node] of Array.from(el('queue').children).entries())node.classList.toggle('selected',j===i);if(matchMedia('(pointer:coarse)').matches)open()}};r.ondblclick=e=>{if(!(e.target as HTMLElement).closest('button'))open()};r.onkeydown=e=>{if(e.key==='Enter'&&e.target===r)open()};return r}
function renderLibrary(){renderFolderNav();const ts=filtered(),l=el('library');l.replaceChildren();el('libcount').textContent=ts.length+' / '+library.length;el('folderSummary').textContent=ts.length+' треков в выборке';btn('addAll').disabled=!ts.length;const fragment=document.createDocumentFragment();ts.slice(0,5000).forEach((t,i)=>fragment.append(row(t,i,false)));l.append(fragment);if(!ts.length){const e=document.createElement('p');e.className='empty';e.textContent=libraryView==='likes'?'Здесь появятся понравившиеся композиции.':libraryView==='recent'?'Здесь появятся недавно прослушанные композиции.':library.length?'Ничего не найдено. Попробуйте изменить фильтры.':identity.role==='admin'?'Библиотека пуста. Добавьте музыку в разделе управления.':'В библиотеке пока нет музыки.';l.append(e)}if(ts.length>5000)message('Показаны первые 5000 треков. Используйте фильтр.')}
