async function fetchSaved(){try{const id=identity;const pub=await api<Playlist[]>('playlists');const personal=id.role==='guest'?[]:await api<Playlist[]>('personal-playlists');if(id!==identity)return;saved=[...pub.map(p=>({...p,scope:'public' as const})),...personal.map(p=>({...p,scope:'personal' as const}))];renderLists();}catch(e){message(String(e))}}
function remove(){if(selected<0||selected>=queue.length)return;const i=selected;if(i===current){stopPlayback();current=-1}else if(i<current)current--;queue.splice(i,1);selected=Math.min(i,queue.length-1);bag=[];history=[];failed.clear();renderQueue();updateNow()}
function move(d:number){const j=selected+d;if(selected<0||j<0||j>=queue.length)return;const i=selected;[queue[i],queue[j]]=[queue[j],queue[i]];if(current===i)current=j;else if(current===j)current=i;selected=j;bag=[];history=[];renderQueue()}
function localFiles(files:File[]){const tracks:Track[]=[];for(const f of files){const ext=f.name.split('.').at(-1)?.toLowerCase()??'',ay=!!formatOf(f.name);if((ay&&f.size<=65536)||['mp3','flac','wav','ogg','opus','m4a','aac'].includes(ext)){tracks.push({id:'local:'+f.name+':'+f.size+':'+f.lastModified,name:f.name,path:f.name,source:'local',format:ext,size:f.size,mode:ay?'ay':'native',file:f})}}add(tracks);message('Локально добавлено: '+tracks.length+'; файлы не отправлены на сервер')}
type ZipReport={path:string,tracks:number,archives:number,duplicates:number,skipped:number,bytes:number,badArchives?:number,badFiles?:number,warnings?:string[]};
function uploadArchive(file:File,dir:string,label:string):Promise<ZipReport>{return new Promise((resolve,reject)=>{const request=new XMLHttpRequest(),progress=el<HTMLProgressElement>('uploadProgress');request.open('POST','/api/import-zip?dir='+encodeURIComponent(dir));request.setRequestHeader('X-RuneAmp-Request','1');request.upload.onprogress=e=>{if(e.lengthComputable){progress.value=e.loaded/e.total*100;el('uploadStatus').textContent=label+' · '+Math.round(progress.value)+'%'}};request.upload.onload=()=>{progress.removeAttribute('value');el('uploadStatus').textContent=label+' · распаковка и индексация…'};request.onload=()=>{try{const data=JSON.parse(request.responseText);if(request.status<200||request.status>=300)throw Error(data.error??'HTTP '+request.status);resolve(data as ZipReport)}catch(e){reject(e)}};request.onerror=()=>reject(Error('Ошибка соединения'));request.onabort=()=>reject(Error('Загрузка прервана'));const form=new FormData();form.append('file',file);request.send(form)})}
async function upload(files:File[]){if(identity.role!=='admin'||!files.length||btn('upload').disabled)return;btn('upload').disabled=btn('uploadZip').disabled=btn('rescan').disabled=true;const dir=select('uploadDir').value;let count=0,archives=0,duplicates=0,skipped=0,badArchives=0,badFiles=0,lastPath='';const problems:string[]=[],warnings:string[]=[];const progress=el<HTMLProgressElement>('uploadProgress');progress.hidden=false;try{for(const [i,f] of files.entries()){const label='Загрузка '+(i+1)+' / '+files.length+' · '+f.name;el('uploadStatus').textContent=label;progress.value=0;try{if(/\.zip$/i.test(f.name)){const report=await uploadArchive(f,dir,label);count+=report.tracks;archives+=report.archives;duplicates+=report.duplicates;skipped+=report.skipped;badArchives+=report.badArchives??0;badFiles+=report.badFiles??0;for(const warning of report.warnings??[]){if(warnings.length<10)warnings.push(warning)}lastPath=report.path}else{const form=new FormData();form.append('file',f);progress.removeAttribute('value');await api<Track>('upload?dir='+encodeURIComponent(dir),'POST',form);count++}}catch(e){problems.push(f.name+': '+String(e))}}const summary='Загружено: '+count+' треков'+(archives?' · ZIP обработано: '+archives+' · дубликатов: '+duplicates+' · пропущено: '+skipped:'')+(badArchives||badFiles?' · битых/неподдерживаемых ZIP: '+badArchives+' · повреждённых файлов: '+badFiles:'')+(warnings.length?' · '+warnings.join('; '):'')+(problems.length?' · '+problems.join('; '):'');el('uploadStatus').textContent='Обновление библиотеки…';try{setLibrary(await api<Track[]>('rescan','POST'));await fetchFolders();if(lastPath){select('browseSource').value=writable?'music':'uploads';await fetchFolders();select('browseDir').value=lastPath}await browseFolder();el('uploadStatus').textContent=summary+' · библиотека обновлена'}catch(e){el('uploadStatus').textContent=summary+' · ошибка пересканирования: '+String(e)}}finally{progress.hidden=true;btn('upload').disabled=btn('uploadZip').disabled=btn('rescan').disabled=false}}
btn('uploadZip').onclick=()=>input('zipFiles').click();input('zipFiles').onchange=()=>{void upload(Array.from(input('zipFiles').files??[]));input('zipFiles').value=''};
btn('rescan').onclick=async()=>{if(identity.role!=='admin')return;btn('rescan').disabled=true;el('uploadStatus').textContent='Пересканирование…';try{setLibrary(await api<Track[]>('rescan','POST'));await fetchFolders();await browseFolder();el('uploadStatus').textContent='Библиотека обновлена · '+library.length+' треков'}catch(e){el('uploadStatus').textContent=String(e)}finally{btn('rescan').disabled=false}};input('search').oninput=renderLibrary;select('source').onchange=()=>{folderPage=0;renderLibrary()};input('folderRecursive').onchange=renderLibrary;input('folderSearch').oninput=()=>{folderPage=0;renderFolderNav()};btn('folderUp').onclick=()=>browseLibraryFolder(folderPath.includes('/')?folderPath.slice(0,folderPath.lastIndexOf('/')):'');btn('folderPrev').onclick=()=>{folderPage--;renderFolderNav()};btn('folderNext').onclick=()=>{folderPage++;renderFolderNav()};btn('addAll').onclick=()=>add(filtered());
