btn('play').onclick=togglePlay;btn('stop').onclick=()=>{stopPlayback();updateNow()};btn('next').onclick=()=>{failed.clear();advance()};btn('prev').onclick=()=>{failed.clear();const p=history.pop();void playAt(p??(current<0?queue.length-1:(current-1+queue.length)%queue.length),false)};
