async function browseFolder(){if(identity.role!=='admin')return;const g=++browseGeneration,source=select('browseSource').value,dir=select('browseDir').value||'.';const target=el('folderContents');target.textContent='Чтение папки…';try{const data=await api<{entries:FolderEntry[],tracks:number,folders:number,truncated:boolean}>('admin/folder?source='+encodeURIComponent(source)+'&dir='+encodeURIComponent(dir));if(g!==browseGeneration||identity.role!=='admin')return;target.replaceChildren();el('folderCount').textContent=data.tracks+' треков · '+data.folders+' папок'+(data.truncated?' · ограниченный список':'');if(dir!=='.')target.append(action('← Родительская папка',()=>{select('browseDir').value=dir.includes('/')?dir.slice(0,dir.lastIndexOf('/')):'.';void browseFolder()}));for(const e of data.entries){const r=infoRow((e.directory?'▸ ':'')+e.name,e.directory?'Папка':(e.music?(e.format??'').toUpperCase():'Другой файл')+' · '+Math.round((e.size??0)/1024)+' КиБ · '+(e.music?(e.indexed?'В библиотеке':'Не индексирован'):'Не музыка'));if(e.directory)r.append(action('Открыть',()=>{select('browseDir').value=e.path;void browseFolder()}));else if(e.indexed){const t=library.find(t=>t.source===source&&t.path===e.path);if(t)r.append(action('▶',()=>{add([t]);void playAt(queue.findIndex(x=>x.id===t.id))}))}if(source==='uploads'||writable){const del=action('Удалить',()=>void deleteMusic(source,e));del.className='danger';del.setAttribute('aria-label','Удалить '+e.name);r.append(del)}target.append(r)}if(!data.entries.length)target.append('Папка пуста.')}catch(e){if(g===browseGeneration)target.textContent=String(e)}}
let deleting=false;
